You can just write a custom cout operator for vector like this: (Also can be done with pair, set, etc.)

// using std::ostream - You may need this line.

template<typename T>
ostream &operator << (ostream &os, vector<T> vec) {
	for(int i = 0; i < vec.size(); i++) {
		os << vec[i] << " ";
	}
	return os;
}

